  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","boss","defeated","tag","hitGap","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  boss: "THE OLD WORKFLOW",
  defeated: "DEFEATED",
  tag: "BOSS",
  hitGap: 26,
  accent: "#3B5BFD",
  fontFamily: "Chakra Petch",
  scale: 1,
  delay: 0,
  speed: 1,
};

type BossBarElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BossBarBase>;

const BossBarInner = forwardRef<
  HTMLDivElement,
  BossBarElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BossBar>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BossBarBase
          {...(componentProps as unknown as ComponentProps<typeof BossBarBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BossBar = Interactive.withSchema({
  Component: BossBarInner,
  componentName: "<BossBar>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
